function PROOF_COMPLEXITY(n):
    if n < 2: return 0
    count <- 0; d <- 2; m <- n
    while d*d <= m:
        while m mod d == 0:
            count <- count + 1; m <- m / d
        d <- d + 1
    if m > 1: count <- count + 1
    return count
function IS_ANTI_GRAVITY(n):
    return 2 ^ PROOF_COMPLEXITY(n) == n

